var ROLES=['资深前端工程师','英语母语编辑','数据分析师','产品经理','历史老师','健身教练','心理咨询师'];
var TASKS=['解释一个复杂概念','写一段示例代码','总结要点','生成对比表格','给出改进建议','设计一个工作流'];
var FMTS=['用要点列出','以 Markdown 表格输出','用通俗比喻说明','分步骤讲解','附一句总结'];
var CONS=['面向初学者','控制在 200 字内','给出可运行示例','避免专业术语','用中文回答'];
function pick(arr, rng){ return arr[Math.floor(rng()*arr.length)]; }
function generate(rng){
  rng=rng||Math.random;
  return '角色：'+pick(ROLES,rng)+'\n任务：'+pick(TASKS,rng)+'\n格式：'+pick(FMTS,rng)+'\n约束：'+pick(CONS,rng);
}
var EXPORTS={ROLES:ROLES,TASKS:TASKS,FMTS:FMTS,CONS:CONS,generate:generate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PromptIdeaForgePure = EXPORTS; }
